-- Tests psychotechniques : nouvelle matière pour tous les niveaux, avec cours de méthode et QCM
do $psy$
declare v_m uuid; v_ch uuid; v_q uuid; x jsonb; o jsonb; p int; i int := 0;
begin
  insert into public.matieres (nom, code, ordre, tous_niveaux)
  select 'Tests psychotechniques', 'PT', 12, true where not exists (select 1 from public.matieres where code = 'PT');
  select id into v_m from public.matieres where code = 'PT';
  foreach x in array array(select jsonb_array_elements($j$["Séries de nombres", "Séries de lettres", "Analogies et intrus", "Logique et raisonnement", "Calcul rapide"]$j$::jsonb)) loop
    i := i + 1;
    insert into public.chapitres (matiere_id, nom, ordre)
    select v_m, x #>> '{}', i where not exists (select 1 from public.chapitres where matiere_id = v_m and nom = x #>> '{}');
  end loop;
  for x in select jsonb_array_elements($j$[{"ch": "Séries de nombres", "d": 1, "e": "Complétez la série : 2 ; 4 ; 8 ; 16 ; ...", "ex": "Chaque nombre est le double du précédent : 16 × 2 = 32.", "o": [["36", false], ["32", true], ["24", false], ["30", false]]}, {"ch": "Séries de nombres", "d": 1, "e": "Complétez la série : 3 ; 6 ; 9 ; 12 ; ...", "ex": "On ajoute 3 à chaque fois : 12 + 3 = 15.", "o": [["18", false], ["16", false], ["15", true], ["14", false]]}, {"ch": "Séries de nombres", "d": 1, "e": "Complétez la série : 100 ; 90 ; 80 ; 70 ; ...", "ex": "On retire 10 à chaque fois : 70 − 10 = 60.", "o": [["75", false], ["60", true], ["50", false], ["65", false]]}, {"ch": "Séries de nombres", "d": 2, "e": "Complétez la série : 1 ; 4 ; 9 ; 16 ; 25 ; ...", "ex": "Ce sont les carrés des entiers : 1², 2², 3², 4², 5², donc 6² = 36.", "o": [["49", false], ["36", true], ["35", false], ["30", false]]}, {"ch": "Séries de nombres", "d": 2, "e": "Complétez la série : 5 ; 10 ; 20 ; 40 ; ...", "ex": "Chaque terme est multiplié par 2 : 40 × 2 = 80.", "o": [["100", false], ["60", false], ["80", true], ["70", false]]}, {"ch": "Séries de nombres", "d": 2, "e": "Complétez la série : 1 ; 1 ; 2 ; 3 ; 5 ; 8 ; ...", "ex": "Chaque terme est la somme des deux précédents : 5 + 8 = 13 (suite de Fibonacci).", "o": [["12", false], ["16", false], ["13", true], ["11", false]]}, {"ch": "Séries de nombres", "d": 2, "e": "Complétez la série : 2 ; 3 ; 5 ; 7 ; 11 ; ...", "ex": "Ce sont les nombres premiers dans l'ordre : après 11 vient 13.", "o": [["13", true], ["14", false], ["15", false], ["12", false]]}, {"ch": "Séries de nombres", "d": 3, "e": "Complétez la série : 2 ; 6 ; 12 ; 20 ; 30 ; ...", "ex": "Les écarts augmentent de 2 à chaque fois : +4, +6, +8, +10, puis +12. 30 + 12 = 42.", "o": [["40", false], ["36", false], ["44", false], ["42", true]]}, {"ch": "Séries de nombres", "d": 3, "e": "Complétez la série : 1 ; 3 ; 7 ; 15 ; 31 ; ...", "ex": "Chaque terme est le double du précédent plus 1 : 31 × 2 + 1 = 63.", "o": [["47", false], ["62", false], ["63", true], ["65", false]]}, {"ch": "Séries de nombres", "d": 3, "e": "Complétez la série : 81 ; 27 ; 9 ; 3 ; ...", "ex": "Chaque terme est divisé par 3 : 3 ÷ 3 = 1.", "o": [["6", false], ["2", false], ["1", true], ["0", false]]}, {"ch": "Séries de nombres", "d": 3, "e": "Complétez la série : 1 ; 2 ; 4 ; 5 ; 7 ; 8 ; ...", "ex": "On ajoute tantôt 1, tantôt 2, en alternance : 8 + 2 = 10.", "o": [["10", true], ["12", false], ["11", false], ["9", false]]}, {"ch": "Séries de nombres", "d": 3, "e": "Complétez la série : 20 ; 18 ; 15 ; 11 ; ...", "ex": "On retire 2, puis 3, puis 4, puis 5 : 11 − 5 = 6.", "o": [["7", false], ["8", false], ["9", false], ["6", true]]}, {"ch": "Séries de lettres", "d": 1, "e": "Complétez la série : A ; C ; E ; G ; ...", "ex": "On saute une lettre à chaque fois : A, C, E, G, I.", "o": [["H", false], ["K", false], ["I", true], ["J", false]]}, {"ch": "Séries de lettres", "d": 1, "e": "Complétez la série : Z ; X ; V ; T ; ...", "ex": "On recule de deux lettres à chaque fois : T, puis R.", "o": [["S", false], ["Q", false], ["R", true], ["P", false]]}, {"ch": "Séries de lettres", "d": 2, "e": "Complétez la série : A ; B ; D ; G ; ...", "ex": "Les écarts sont 1, 2, 3, puis 4 : G (7) + 4 = K (11).", "o": [["M", false], ["K", true], ["J", false], ["L", false]]}, {"ch": "Séries de lettres", "d": 3, "e": "Complétez la série : B ; D ; G ; K ; ...", "ex": "Les écarts sont 2, 3, 4, puis 5 : K (11) + 5 = P (16).", "o": [["N", false], ["P", true], ["Q", false], ["O", false]]}, {"ch": "Séries de lettres", "d": 2, "e": "Complétez la série : AZ ; BY ; CX ; ...", "ex": "La première lettre avance (A, B, C, D) pendant que la seconde recule (Z, Y, X, W).", "o": [["DY", false], ["DW", true], ["EW", false], ["DV", false]]}, {"ch": "Séries de lettres", "d": 1, "e": "Complétez la série : LUNDI ; MARDI ; MERCREDI ; JEUDI ; ...", "ex": "On suit les jours de la semaine : après jeudi vient vendredi.", "o": [["VENDREDI", true], ["LUNDI", false], ["DIMANCHE", false], ["SAMEDI", false]]}, {"ch": "Analogies et intrus", "d": 1, "e": "Chaud est à froid comme grand est à :", "ex": "Chaud et froid sont des contraires ; le contraire de grand est petit.", "o": [["haut", false], ["petit", true], ["large", false], ["gros", false]]}, {"ch": "Analogies et intrus", "d": 1, "e": "Médecin est à hôpital comme enseignant est à :", "ex": "Le lieu de travail du médecin est l'hôpital ; celui de l'enseignant est l'école.", "o": [["marché", false], ["tribunal", false], ["école", true], ["gare", false]]}, {"ch": "Analogies et intrus", "d": 1, "e": "Oiseau est à nid comme abeille est à :", "ex": "Le nid est la maison de l'oiseau ; la ruche est celle de l'abeille.", "o": [["fleur", false], ["aile", false], ["miel", false], ["ruche", true]]}, {"ch": "Analogies et intrus", "d": 2, "e": "Pied est à chaussure comme main est à :", "ex": "La chaussure habille le pied ; le gant habille la main.", "o": [["manche", false], ["gant", true], ["doigt", false], ["bague", false]]}, {"ch": "Analogies et intrus", "d": 1, "e": "Doigt est à main comme orteil est à :", "ex": "Le doigt fait partie de la main ; l'orteil fait partie du pied.", "o": [["pied", true], ["jambe", false], ["talon", false], ["genou", false]]}, {"ch": "Analogies et intrus", "d": 1, "e": "Lequel est l'intrus : lion ; tigre ; panthère ; requin ?", "ex": "Le lion, le tigre et la panthère sont des félins. Le requin est un poisson.", "o": [["panthère", false], ["lion", false], ["tigre", false], ["requin", true]]}, {"ch": "Analogies et intrus", "d": 1, "e": "Lequel est l'intrus : mil ; sorgho ; maïs ; igname ?", "ex": "Le mil, le sorgho et le maïs sont des céréales. L'igname est un tubercule.", "o": [["sorgho", false], ["mil", false], ["maïs", false], ["igname", true]]}, {"ch": "Analogies et intrus", "d": 1, "e": "Lequel est l'intrus : Ouagadougou ; Bobo-Dioulasso ; Koudougou ; Abidjan ?", "ex": "Les trois premières villes sont au Burkina Faso. Abidjan est en Côte d'Ivoire.", "o": [["Bobo-Dioulasso", false], ["Ouagadougou", false], ["Koudougou", false], ["Abidjan", true]]}, {"ch": "Analogies et intrus", "d": 2, "e": "Lequel est l'intrus : triangle ; carré ; cercle ; cube ?", "ex": "Le triangle, le carré et le cercle sont des figures planes. Le cube est un solide.", "o": [["cercle", false], ["cube", true], ["triangle", false], ["carré", false]]}, {"ch": "Logique et raisonnement", "d": 1, "e": "Tous les A sont des B, et tous les B sont des C. On peut conclure que :", "ex": "Si A est inclus dans B et B dans C, alors A est inclus dans C.", "o": [["aucun A n'est un C", false], ["certains B ne sont pas des A", false], ["tous les C sont des A", false], ["tous les A sont des C", true]]}, {"ch": "Logique et raisonnement", "d": 1, "e": "Tous les oiseaux ont des plumes. Le pigeon est un oiseau. Donc :", "ex": "Le pigeon appartient aux oiseaux, qui ont tous des plumes.", "o": [["le pigeon vole toujours", false], ["le pigeon est un mammifère", false], ["tout ce qui a des plumes est un pigeon", false], ["le pigeon a des plumes", true]]}, {"ch": "Logique et raisonnement", "d": 1, "e": "Awa est plus grande que Binta, et Binta est plus grande que Claire. Qui est la plus grande ?", "ex": "Awa > Binta > Claire : Awa est la plus grande.", "o": [["Claire", false], ["On ne peut pas savoir", false], ["Awa", true], ["Binta", false]]}, {"ch": "Logique et raisonnement", "d": 1, "e": "Paul arrive avant Marc, et Marc arrive avant Luc. Qui arrive en dernier ?", "ex": "L'ordre d'arrivée est Paul, Marc, Luc : Luc est le dernier.", "o": [["On ne peut pas savoir", false], ["Marc", false], ["Paul", false], ["Luc", true]]}, {"ch": "Logique et raisonnement", "d": 2, "e": "Hier, nous étions lundi. Quel jour serons-nous après-demain ?", "ex": "Hier lundi, donc aujourd'hui mardi, demain mercredi et après-demain jeudi.", "o": [["mercredi", false], ["vendredi", false], ["mardi", false], ["jeudi", true]]}, {"ch": "Logique et raisonnement", "d": 2, "e": "Le 5 du mois est un lundi. Quel jour est le 19 du même mois ?", "ex": "Du 5 au 19, il y a 14 jours, soit exactement deux semaines : on retombe sur un lundi.", "o": [["mardi", false], ["samedi", false], ["lundi", true], ["dimanche", false]]}, {"ch": "Logique et raisonnement", "d": 2, "e": "Je marche vers le nord, je tourne à droite, puis encore à droite. Vers quelle direction est-ce que je regarde ?", "ex": "Nord, puis un quart de tour à droite : est ; encore un quart de tour à droite : sud.", "o": [["le nord", false], ["l'ouest", false], ["le sud", true], ["l'est", false]]}, {"ch": "Logique et raisonnement", "d": 2, "e": "Dans un code où A = 1, B = 2, C = 3 et ainsi de suite, le mot BAC s'écrit :", "ex": "B = 2, A = 1, C = 3.", "o": [["1 – 2 – 3", false], ["3 – 1 – 2", false], ["2 – 3 – 1", false], ["2 – 1 – 3", true]]}, {"ch": "Logique et raisonnement", "d": 3, "e": "Un père a 40 ans et son fils 10 ans. Dans combien d'années le père aura-t-il exactement trois fois l'âge de son fils ?", "ex": "Dans 5 ans : père 45, fils 15, et 45 = 3 × 15.", "o": [["5 ans", true], ["10 ans", false], ["15 ans", false], ["20 ans", false]]}, {"ch": "Logique et raisonnement", "d": 3, "e": "Dans 5 ans, Kader aura le double de l'âge qu'il avait il y a 5 ans. Quel âge a-t-il aujourd'hui ?", "ex": "À 15 ans : dans 5 ans il aura 20 ans, et il y a 5 ans il avait 10 ans ; 20 = 2 × 10.", "o": [["15 ans", true], ["10 ans", false], ["20 ans", false], ["25 ans", false]]}, {"ch": "Logique et raisonnement", "d": 3, "e": "Si 5 machines fabriquent 5 pièces en 5 minutes, combien de temps faut-il à 100 machines pour fabriquer 100 pièces ?", "ex": "Chaque machine fabrique une pièce en 5 minutes : 100 machines font donc 100 pièces en 5 minutes.", "o": [["100 minutes", false], ["50 minutes", false], ["20 minutes", false], ["5 minutes", true]]}, {"ch": "Logique et raisonnement", "d": 2, "e": "Combien de fois la lettre E apparaît-elle dans le mot EXERCICE ?", "ex": "E-X-E-R-C-I-C-E : la lettre E est en première, troisième et dernière position.", "o": [["3", true], ["2", false], ["1", false], ["4", false]]}, {"ch": "Logique et raisonnement", "d": 2, "e": "On a 2 → 8 ; 3 → 27 ; 4 → 64. Par quel nombre 5 est-il remplacé ?", "ex": "Chaque nombre est élevé au cube : 5³ = 125.", "o": [["625", false], ["125", true], ["100", false], ["120", false]]}, {"ch": "Logique et raisonnement", "d": 2, "e": "On a (2 ; 4) ; (3 ; 9) ; (4 ; 16). Quel nombre complète (5 ; ...) ?", "ex": "Le second nombre est le carré du premier : 5² = 25.", "o": [["36", false], ["20", false], ["24", false], ["25", true]]}, {"ch": "Calcul rapide", "d": 1, "e": "Combien font 20 % de 150 ?", "ex": "20 % de 150 = 150 × 20 ÷ 100 = 30.", "o": [["20", false], ["25", false], ["35", false], ["30", true]]}, {"ch": "Calcul rapide", "d": 2, "e": "Un article coûte 2 000 F. Avec une remise de 25 %, son prix devient :", "ex": "25 % de 2 000 = 500 ; 2 000 − 500 = 1 500.", "o": [["500 F", false], ["1 750 F", false], ["1 500 F", true], ["1 000 F", false]]}, {"ch": "Calcul rapide", "d": 1, "e": "Trois stylos coûtent 450 F. Combien coûtent cinq stylos ?", "ex": "Un stylo coûte 450 ÷ 3 = 150 F ; cinq stylos coûtent 5 × 150 = 750 F.", "o": [["600 F", false], ["900 F", false], ["700 F", false], ["750 F", true]]}, {"ch": "Calcul rapide", "d": 1, "e": "Un train parcourt 120 km en 2 heures. Sa vitesse moyenne est de :", "ex": "Vitesse = distance ÷ temps = 120 ÷ 2 = 60 km/h.", "o": [["100 km/h", false], ["240 km/h", false], ["40 km/h", false], ["60 km/h", true]]}, {"ch": "Calcul rapide", "d": 1, "e": "Quelle est la moyenne de 10 ; 12 et 14 ?", "ex": "(10 + 12 + 14) ÷ 3 = 36 ÷ 3 = 12.", "o": [["36", false], ["11", false], ["13", false], ["12", true]]}, {"ch": "Calcul rapide", "d": 1, "e": "Combien font 15 × 12 ?", "ex": "15 × 12 = 15 × 10 + 15 × 2 = 150 + 30 = 180.", "o": [["180", true], ["190", false], ["150", false], ["170", false]]}, {"ch": "Calcul rapide", "d": 2, "e": "Quel angle forment les aiguilles d'une horloge à 3 heures précises ?", "ex": "À 3 heures, la petite aiguille est sur le 3 et la grande sur le 12 : un quart de tour, soit 90°.", "o": [["45°", false], ["60°", false], ["90°", true], ["180°", false]]}, {"ch": "Calcul rapide", "d": 2, "e": "Un commerçant achète un sac 8 000 F et le revend 10 000 F. Quel est son bénéfice en pourcentage du prix d'achat ?", "ex": "Bénéfice = 2 000 F ; 2 000 ÷ 8 000 = 0,25, soit 25 %.", "o": [["80 %", false], ["25 %", true], ["20 %", false], ["10 %", false]]}, {"ch": "Calcul rapide", "d": 2, "e": "Quelle est la moitié de la moitié de 200 ?", "ex": "La moitié de 200 est 100 ; la moitié de 100 est 50.", "o": [["75", false], ["50", true], ["25", false], ["100", false]]}, {"ch": "Calcul rapide", "d": 3, "e": "Un robinet remplit un seau en 4 minutes. Combien de seaux remplit-il en 20 minutes ?", "ex": "20 ÷ 4 = 5 seaux.", "o": [["5", true], ["10", false], ["4", false], ["6", false]]}]$j$::jsonb) loop
    select id into v_ch from public.chapitres where matiere_id = v_m and nom = x->>'ch';
    if exists (select 1 from public.questions where empreinte = encode(sha256(convert_to('PT|' || (x->>'e'), 'UTF8')), 'hex')) then continue; end if;
    insert into public.questions (matiere_id, chapitre_id, enonce, explication, type_question, difficulte, source, statut, publie_le, empreinte)
    values (v_m, v_ch, x->>'e', x->>'ex', 'qcm', (x->>'d')::int, 'redigee', 'publie', now(), encode(sha256(convert_to('PT|' || (x->>'e'), 'UTF8')), 'hex'))
    returning id into v_q;
    p := 0;
    for o in select jsonb_array_elements(x->'o') loop
      insert into public.question_options (question_id, position, texte, est_correcte) values (v_q, p, o->>0, (o->>1)::boolean);
      p := p + 1;
    end loop;
  end loop;
  for x in select jsonb_array_elements($j$[{"ch": "Séries de nombres", "t": "Réussir les séries de nombres", "r": "Les cinq réflexes pour trouver la règle d'une série numérique.", "c": "Réussir les séries de nombres\n\nUne série de nombres cache toujours une règle simple. Il faut la trouver en moins de 30 secondes.\n\n1. Regardez d'abord les écarts entre deux nombres voisins.\n- 3 ; 6 ; 9 ; 12 : l'écart est toujours 3 (suite arithmétique).\n- 20 ; 18 ; 15 ; 11 : les écarts changent (−2, −3, −4) : cherchez la règle des écarts.\n\n2. Essayez ensuite la multiplication ou la division.\n- 2 ; 4 ; 8 ; 16 : chaque nombre est multiplié par 2.\n- 81 ; 27 ; 9 ; 3 : chaque nombre est divisé par 3.\n\n3. Pensez aux suites connues.\n- Les carrés : 1 ; 4 ; 9 ; 16 ; 25 ; 36.\n- Les cubes : 1 ; 8 ; 27 ; 64 ; 125.\n- Les nombres premiers : 2 ; 3 ; 5 ; 7 ; 11 ; 13.\n- Fibonacci : chaque nombre est la somme des deux précédents (1 ; 1 ; 2 ; 3 ; 5 ; 8 ; 13).\n\n4. Méfiez-vous des séries à deux règles qui alternent (1 ; 2 ; 4 ; 5 ; 7 ; 8 : on ajoute 1, puis 2, puis 1...).\n\n5. Vérifiez votre règle sur tous les nombres de la série avant de répondre, pas seulement sur les deux premiers."}, {"ch": "Séries de lettres", "t": "Réussir les séries de lettres", "r": "Numérotez l'alphabet et traitez les lettres comme des nombres.", "c": "Réussir les séries de lettres\n\nTechnique : remplacez chaque lettre par son rang dans l'alphabet, puis traitez-les comme une série de nombres.\n\nA=1 B=2 C=3 D=4 E=5 F=6 G=7 H=8 I=9 J=10 K=11 L=12 M=13\nN=14 O=15 P=16 Q=17 R=18 S=19 T=20 U=21 V=22 W=23 X=24 Y=25 Z=26\n\nExemples\n- A ; C ; E ; G ; I : on saute une lettre à chaque fois (+2).\n- B ; D ; G ; K ; P : écarts 2, 3, 4, 5.\n- AZ ; BY ; CX ; DW : la première lettre avance, la seconde recule.\n\nAstuce : écrivez l'alphabet en haut de la feuille de brouillon avant de commencer, cela prend 10 secondes."}, {"ch": "Analogies et intrus", "t": "Réussir les analogies et trouver l'intrus", "r": "Trouver le lien logique entre deux mots, puis l'appliquer au troisième.", "c": "Réussir les analogies et trouver l'intrus\n\nL'analogie « A est à B comme C est à ... » demande de trouver le lien entre A et B, puis de le reproduire avec C.\n\nLes liens les plus fréquents\n- Le contraire : chaud / froid, grand / petit.\n- Le lieu de travail : médecin / hôpital, enseignant / école.\n- La partie et le tout : doigt / main, orteil / pied.\n- L'habitation : oiseau / nid, abeille / ruche.\n- L'objet et son usage : stylo / écrire, couteau / couper.\n\nMéthode : dites la relation dans une phrase (« le nid est la maison de l'oiseau »), puis répétez la même phrase avec le troisième mot.\n\nL'intrus : trouvez la catégorie commune à trois mots sur quatre (félins, céréales, villes d'un même pays, figures planes). Le mot qui n'y entre pas est l'intrus."}, {"ch": "Logique et raisonnement", "t": "Réussir les questions de logique", "r": "Syllogismes, classements, âges, calendrier et directions.", "c": "Réussir les questions de logique\n\n1. Les syllogismes : si tous les A sont des B et tous les B sont des C, alors tous les A sont des C. Ne concluez jamais plus que ce que les phrases disent.\n\n2. Les classements : placez les personnes sur une ligne. Awa > Binta > Claire : Awa est la plus grande.\n\n3. Les problèmes d'âge : écrivez l'âge actuel avec une lettre (x), traduisez la phrase en équation, puis testez la réponse.\n\n4. Le calendrier : une semaine = 7 jours. Dans 14 jours, on tombe sur le même jour de la semaine.\n\n5. Les directions : un quart de tour à droite depuis le nord mène à l'est, puis au sud, puis à l'ouest. Dessinez une petite boussole sur votre brouillon.\n\n6. Les codes : numérotez l'alphabet (A=1, B=2...) et appliquez le code lettre par lettre."}, {"ch": "Calcul rapide", "t": "Réussir le calcul rapide", "r": "Pourcentages, proportions, moyennes et vitesse sans calculatrice.", "c": "Réussir le calcul rapide\n\n- 10 % d'un nombre : on divise par 10. 20 % : on divise par 5. 25 % : on divise par 4. 50 % : on divise par 2.\n- Une remise de 25 % sur 2 000 F : 2 000 ÷ 4 = 500 F de remise, donc 1 500 F à payer.\n- La règle de trois : 3 stylos coûtent 450 F, donc 1 stylo coûte 450 ÷ 3 = 150 F, et 5 stylos coûtent 750 F.\n- La moyenne : on additionne les valeurs, puis on divise par leur nombre.\n- La vitesse : vitesse = distance ÷ temps.\n- Multiplier par 12 : multipliez par 10, puis par 2, et additionnez (15 × 12 = 150 + 30 = 180).\n- L'horloge : chaque heure représente 30° (360° ÷ 12). À 3 heures, l'angle est de 90°.\n\nGagnez du temps : si une question vous bloque plus d'une minute, passez à la suivante et revenez-y à la fin."}]$j$::jsonb) loop
    insert into public.cours (matiere_id, chapitre_id, titre, resume, contenu, source, statut, publie_le)
    select v_m, (select id from public.chapitres where matiere_id = v_m and nom = x->>'ch'), x->>'t', x->>'r', x->>'c', 'redigee', 'publie', now()
    where not exists (select 1 from public.cours where matiere_id = v_m and titre = x->>'t');
  end loop;
end $psy$;
